// Dipisah dari Fund Insight. Login lewat Tool Hub (app "competitor").
// Bindings: DB (D1; boleh database yang SAMA dengan Fund Insight supaya data lama & data pasar ikut terbaca),
//           SSO_SECRET (secret, sama dengan Tool Hub), HUB_URL & PROFILE (diisi scripts/deploy.mjs), ADMIN_KEY (opsional, untuk akses lewat skrip).
// Cron: "*/30 * * * *" (scan mingguan Minggu 02.00 WIB, diproses bertahap).
import { profile, title, profileScript } from "../../shared/profile.js";
